def read_file(path, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = secrets.token_bytes(10)
        v = ms
        ts = []
        for _ in range(10):
            ts.append(_ALPH[v % 32])
            v //= 32
        tail = []
        for b in rnd[:16]:
            tail.append(_ALPH[b % 32])
        return prefix + "".join(ts) + "".join(tail)

    def _new_session(rows, now):
        s = {
            "id": _ulid("fs_sess_"),
            "client_name": None,
            "default_base_path": None,
            "default_base_path_set_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "ended_at": None,
        }
        rows.append(s)
        return s

    def _resolve(session, p_in):
        if not isinstance(p_in, str) or not p_in.strip():
            return None, _err("VALIDATION_ERROR", "`path` is required and must be a non-empty string.")
        p = p_in.strip()
        base = session.get("default_base_path")
        if os.path.isabs(p):
            res = os.path.normpath(p)
        else:
            if base is None:
                return None, _err(
                    "VALIDATION_ERROR",
                    "Relative path requires session default_base_path; none set for session.",
                    error_code="INVALID_PATH",
                )
            if not (isinstance(base, str) and os.path.isabs(base)):
                return None, _err(
                    "VALIDATION_ERROR",
                    "Session default_base_path is invalid; must be an absolute path.",
                    error_code="INVALID_PATH",
                )
            res = os.path.normpath(os.path.join(base, p))
        if not os.path.isabs(res):
            return None, _err("VALIDATION_ERROR", "Resolved path must be absolute.", error_code="INVALID_PATH")
        return res, None

    def _op_row(op_id, session, params, base_path, src_in, src_res):
        now = _now()
        return {
            "id": op_id,
            "session_id": session["id"],
            "tool_name": "read_file",
            "status": "received",
            "parameters": params,
            "resolved_base_path": base_path,
            "source_path_input": src_in,
            "source_path_resolved": src_res,
            "destination_path_input": None,
            "destination_path_resolved": None,
            "node_id": None,
            "destination_node_id": None,
            "result_summary": None,
            "error_code": None,
            "error_message": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }

    def _set_status(op, new_status):
        transitions = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = op.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        op["status"] = new_status
        op["updated_at"] = _now()
        return True

    t0 = time.time()

    if not isinstance(path, str) or not path.strip():
        # still record operation attempt if possible (requires a session); but without valid params we can't resolve.
        return _err("VALIDATION_ERROR", "`path` is required and must be a non-empty string.")

    path_in = path.strip()

    sessions = _load("sessions.json")
    ops = _load("filesystem_operations.json")
    nodes = _load("filesystem_nodes.json")
    versions = _load("file_versions.json")

    # Ambient auth/session resolution:
    # - Prefer an active session that can resolve the provided path (relative requires default_base_path absolute).
    # - If none exists, create a new session (rule: ended sessions must not accept new ops).
    chosen = None
    if os.path.isabs(path_in):
        for s in sessions:
            if s.get("status") == "active":
                chosen = s
                break
    else:
        for s in sessions:
            if s.get("status") == "active":
                dbp = s.get("default_base_path")
                if isinstance(dbp, str) and os.path.isabs(dbp):
                    chosen = s
                    break
    if chosen is None:
        chosen = _new_session(sessions, _now())
        _save("sessions.json", sessions)

    op_id = _ulid("fs_op_")
    base_path = chosen.get("default_base_path") if isinstance(chosen.get("default_base_path"), str) else None

    resolved, rerr = _resolve(chosen, path_in)
    op = _op_row(op_id, chosen, {"path": path_in}, base_path, path_in, resolved if resolved else None)

    ops.append(op)
    _save("filesystem_operations.json", ops)

    if rerr:
        # fail operation properly
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["started_at"] = op["started_at"] or _now()
        op["finished_at"] = _now()
        op["error_code"] = rerr["error"].get("error_code") or rerr["error"]["code"]
        op["error_message"] = rerr["error"]["message"]
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err(rerr["error"]["code"], rerr["error"]["message"], operation_id=op_id, resolved_path=op["source_path_resolved"], latency_ms=latency_ms)

    # Start running
    if not _set_status(op, "running"):
        op["status"] = "running"
        op["updated_at"] = _now()
    op["started_at"] = _now()
    _save("filesystem_operations.json", ops)

    # Read the actual filesystem
    try:
        st = os.stat(resolved)
    except FileNotFoundError:
        op["error_code"] = "NOT_FOUND"
        op["error_message"] = "Resolved path does not exist."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Resolved path does not exist.", operation_id=op_id, resolved_path=resolved, latency_ms=latency_ms)
    except PermissionError:
        op["error_code"] = "UNAUTHORIZED"
        op["error_message"] = "Permission denied reading the resolved path."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Permission denied reading the resolved path.", operation_id=op_id, resolved_path=resolved, latency_ms=latency_ms)

    if not os.path.isfile(resolved):
        op["error_code"] = "CONFLICT"
        op["error_message"] = "Resolved path is not a regular file."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", "Resolved path is not a regular file.", operation_id=op_id, resolved_path=resolved, latency_ms=latency_ms)

    try:
        with open(resolved, "r", encoding="utf-8") as f:
            content = f.read()
    except FileNotFoundError:
        op["error_code"] = "NOT_FOUND"
        op["error_message"] = "Resolved path does not exist."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Resolved path does not exist.", operation_id=op_id, resolved_path=resolved, latency_ms=latency_ms)
    except UnicodeDecodeError:
        op["error_code"] = "CONFLICT"
        op["error_message"] = "File is not valid UTF-8 text."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", "File is not valid UTF-8 text.", operation_id=op_id, resolved_path=resolved, latency_ms=latency_ms)
    except PermissionError:
        op["error_code"] = "UNAUTHORIZED"
        op["error_message"] = "Permission denied reading the resolved path."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Permission denied reading the resolved path.", operation_id=op_id, resolved_path=resolved, latency_ms=latency_ms)

    # Upsert filesystem_nodes for this file
    now = _now()
    h = hashlib.sha256(content.encode("utf-8")).hexdigest()
    size_bytes = len(content.encode("utf-8"))

    node = None
    for n in nodes:
        if n.get("canonical_path") == resolved:
            node = n
            break

    if node is None:
        node = {
            "id": _ulid("fs_node_"),
            "canonical_path": resolved,
            "node_type": "file",
            "exists_flag": True,
            "size_bytes": size_bytes,
            "content_hash_sha256": h,
            "last_seen_at": now,
            "status": "present",
            "created_at": now,
            "updated_at": now,
        }
        nodes.append(node)
    else:
        node["node_type"] = "file"
        node["exists_flag"] = True
        node["size_bytes"] = size_bytes
        node["content_hash_sha256"] = h
        node["last_seen_at"] = now
        # lifecycle transition: anything -> present allowed via unknown/deleted->present, present->present is no-op
        if node.get("status") != "present":
            node["status"] = "present"
        node["updated_at"] = now

    op["node_id"] = node["id"]

    # Successful completion
    op["result_summary"] = {"bytes_read": size_bytes}
    if not _set_status(op, "succeeded"):
        op["status"] = "succeeded"
        op["updated_at"] = _now()
    op["finished_at"] = _now()
    _save("filesystem_nodes.json", nodes)
    _save("filesystem_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "content": content,
        "resolved_path": resolved,
        "operation_id": op_id,
        "latency_ms": latency_ms,
    }

def update_file(path, blocks, **_extra):
    import json, os, datetime, time, hashlib, secrets, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = secrets.token_bytes(10)
        v = ms
        ts = []
        for _ in range(10):
            ts.append(_ALPH[v % 32])
            v //= 32
        tail = []
        for b in rnd[:6]:
            tail.append(_ALPH[b % 32])
        return prefix + "".join(ts) + "".join(tail)

    def _pick_active_session(sessions):
        for s in sessions:
            if s.get("status") == "active":
                dbp = s.get("default_base_path")
                if dbp is None or (isinstance(dbp, str) and os.path.isabs(dbp)):
                    return s
        return None

    def _new_session(sessions):
        now = _now()
        s = {
            "id": _ulid("fs_sess_"),
            "client_name": None,
            "default_base_path": None,
            "default_base_path_set_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "ended_at": None,
        }
        sessions.append(s)
        return s

    def _resolve_path(session, p_in):
        if not isinstance(p_in, str) or not p_in.strip():
            return None, "VALIDATION_ERROR", "`path` is required and must be a non-empty string."
        p_in = p_in.strip()
        base = session.get("default_base_path")
        if os.path.isabs(p_in):
            resolved = os.path.normpath(p_in)
        else:
            if base is None:
                return None, "VALIDATION_ERROR", "Relative path requires session default_base_path; none set for session.", "INVALID_PATH"
            if not isinstance(base, str) or not os.path.isabs(base):
                return None, "VALIDATION_ERROR", "Session default_base_path is invalid.", "INVALID_PATH"
            resolved = os.path.normpath(os.path.join(base, p_in))
        if not os.path.isabs(resolved):
            return None, "VALIDATION_ERROR", "Resolved path must be absolute.", "INVALID_PATH"
        if isinstance(base, str) and os.path.isabs(base):
            try:
                if os.path.commonpath([os.path.normpath(base), os.path.normpath(resolved)]) != os.path.normpath(base):
                    return None, "UNAUTHORIZED", "Path is outside the session default base path.", "FORBIDDEN"
            except Exception:
                return None, "UNAUTHORIZED", "Path is outside the session default base path.", "FORBIDDEN"
        return resolved, None, None, None

    def _op_append(ops, op):
        ops.append(op)
        _save("filesystem_operations.json", ops)

    def _op_update(ops, op_id, **fields):
        now = _now()
        for r in ops:
            if r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = now
                _save("filesystem_operations.json", ops)
                return r
        return None

    now = _now()
    sessions = _load("sessions.json")
    ops = _load("filesystem_operations.json")
    nodes = _load("filesystem_nodes.json")
    versions = _load("file_versions.json")
    ublocks = _load("update_blocks.json")

    sess = _pick_active_session(sessions)
    if sess is None or sess.get("status") == "ended":
        sess = _new_session(sessions)
        _save("sessions.json", sessions)

    if not isinstance(blocks, list) or len(blocks) == 0:
        op_id = _ulid("fs_op_")
        op = {
            "id": op_id,
            "session_id": sess["id"],
            "tool_name": "update_file",
            "status": "failed",
            "parameters": {"path": path, "blocks": blocks},
            "resolved_base_path": sess.get("default_base_path"),
            "source_path_input": path,
            "source_path_resolved": None,
            "destination_path_input": None,
            "destination_path_resolved": None,
            "node_id": None,
            "destination_node_id": None,
            "result_summary": None,
            "error_code": "VALIDATION_ERROR",
            "error_message": "`blocks` is required and must be a non-empty array.",
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        _op_append(ops, op)
        return _err("VALIDATION_ERROR", "`blocks` is required and must be a non-empty array.", operation_id=op_id)

    # validate blocks and regex patterns up front
    norm_blocks = []
    for i, b in enumerate(blocks):
        if not isinstance(b, dict):
            return _err("VALIDATION_ERROR", f"Block at index {i} must be an object.")
        if "search" not in b or "replace" not in b:
            return _err("VALIDATION_ERROR", f"Block at index {i} must include 'search' and 'replace'.")
        search = b.get("search")
        replace = b.get("replace")
        if not isinstance(search, str) or not isinstance(replace, str):
            return _err("VALIDATION_ERROR", f"Block at index {i} 'search' and 'replace' must be strings.")
        use_regex = b.get("use_regex", False)
        replace_all = b.get("replace_all", False)
        if not isinstance(use_regex, bool) or not isinstance(replace_all, bool):
            return _err("VALIDATION_ERROR", f"Block at index {i} 'use_regex'/'replace_all' must be boolean when provided.")
        if use_regex:
            try:
                re.compile(search)
            except re.error as e:
                return _err("VALIDATION_ERROR", f"Invalid regex pattern in block {i}: {str(e)}")
        norm_blocks.append({"search": search, "replace": replace, "use_regex": use_regex, "replace_all": replace_all})

    resolved, vcode, vmsg, tool_error_code = _resolve_path(sess, path)

    op_id = _ulid("fs_op_")
    op = {
        "id": op_id,
        "session_id": sess["id"],
        "tool_name": "update_file",
        "status": "received",
        "parameters": {"path": path, "blocks": blocks},
        "resolved_base_path": sess.get("default_base_path"),
        "source_path_input": path,
        "source_path_resolved": resolved,
        "destination_path_input": None,
        "destination_path_resolved": None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    _op_append(ops, op)
    _op_update(ops, op_id, status="running", started_at=_now())

    if vcode:
        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code=tool_error_code or vcode, error_message=vmsg)
        return _err(vcode, vmsg, operation_id=op_id, resolved_path=resolved)

    # Must exist and be a file
    try:
        if not os.path.exists(resolved):
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_FOUND", error_message="File not found.")
            return _err("NOT_FOUND", "File not found.", operation_id=op_id, resolved_path=resolved)
        if os.path.isdir(resolved):
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_A_FILE", error_message="Resolved path is a directory, not a file.")
            return _err("CONFLICT", "Resolved path is not a regular file.", operation_id=op_id, resolved_path=resolved)

        try:
            with open(resolved, "r", encoding="utf-8") as f:
                content = f.read()
        except UnicodeDecodeError:
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_TEXT", error_message="File is not valid UTF-8 text.")
            return _err("CONFLICT", "File is not valid UTF-8 text.", operation_id=op_id, resolved_path=resolved)

        # Record update blocks rows (ordered)
        # enforce unique(operation_id, block_index): remove any existing for op_id (shouldn't exist)
        ublocks = [r for r in ublocks if r.get("operation_id") != op_id]
        for i, b in enumerate(norm_blocks):
            ublocks.append(
                {
                    "id": _ulid("fs_blk_"),
                    "operation_id": op_id,
                    "block_index": i,
                    "search": b["search"],
                    "replace": b["replace"],
                    "use_regex": b["use_regex"],
                    "replace_all": b["replace_all"],
                    "created_at": _now(),
                    "updated_at": _now(),
                }
            )
        _save("update_blocks.json", ublocks)

        new_content = content
        total_replacements = 0
        for b in norm_blocks:
            if b["use_regex"]:
                if b["replace_all"]:
                    new_content, n = re.subn(b["search"], b["replace"], new_content)
                else:
                    new_content, n = re.subn(b["search"], b["replace"], new_content, count=1)
            else:
                if b["replace_all"]:
                    n = new_content.count(b["search"])
                    new_content = new_content.replace(b["search"], b["replace"])
                else:
                    idx = new_content.find(b["search"])
                    if idx == -1:
                        n = 0
                    else:
                        new_content = new_content[:idx] + b["replace"] + new_content[idx + len(b["search"]) :]
                        n = 1
            total_replacements += n

        with open(resolved, "w", encoding="utf-8") as f:
            f.write(new_content)

        bts = new_content.encode("utf-8")
        sha = hashlib.sha256(bts).hexdigest()
        size = len(bts)

        # Upsert node
        node = None
        for r in nodes:
            if r.get("canonical_path") == resolved:
                node = r
                break
        if node is None:
            node = {
                "id": _ulid("fs_node_"),
                "canonical_path": resolved,
                "node_type": "file",
                "exists_flag": True,
                "size_bytes": size,
                "content_hash_sha256": sha,
                "last_seen_at": _now(),
                "status": "present",
                "created_at": _now(),
                "updated_at": _now(),
            }
            nodes.append(node)
        else:
            node["node_type"] = "file"
            node["exists_flag"] = True
            node["size_bytes"] = size
            node["content_hash_sha256"] = sha
            node["last_seen_at"] = _now()
            node["status"] = "present"
            node["updated_at"] = _now()
        _save("filesystem_nodes.json", nodes)

        # New version if content_hash not already exists for this node
        max_ver = 0
        existing_ver = None
        for v in versions:
            if v.get("node_id") == node["id"]:
                vn = v.get("version_number")
                if isinstance(vn, int) and vn > max_ver:
                    max_ver = vn
                if v.get("content_hash_sha256") == sha:
                    existing_ver = v
        if existing_ver is None:
            ver_id = _ulid("fs_ver_")
            ver_num = max_ver + 1
            versions.append(
                {
                    "id": ver_id,
                    "node_id": node["id"],
                    "version_number": ver_num,
                    "content_text": new_content,
                    "content_hash_sha256": sha,
                    "byte_length": size,
                    "created_by_operation_id": op_id,
                    "created_at": _now(),
                    "updated_at": _now(),
                }
            )
            _save("file_versions.json", versions)
        else:
            ver_id = existing_ver.get("id")
            ver_num = existing_ver.get("version_number")

        fin = _now()
        _op_update(
            ops,
            op_id,
            status="succeeded",
            finished_at=fin,
            node_id=node["id"],
            result_summary={
                "replacements": total_replacements,
                "bytes_written": size,
                "version_id": ver_id,
                "version_number": ver_num,
            },
        )
        return {
            "resolved_path": resolved,
            "node_id": node["id"],
            "replacements": total_replacements,
            "bytes_written": size,
            "version_id": ver_id,
            "version_number": ver_num,
            "operation_id": op_id,
            "content": new_content,
        }
    except Exception as e:
        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code="FAILED", error_message=str(e))
        return _err("CONFLICT", "Unable to update file.", operation_id=op_id, resolved_path=resolved)

def list_files(path, recursive=None, maxEntries=None, **_extra):
    import json, os, datetime, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = secrets.token_bytes(10)
        v = ms
        ts = []
        for _ in range(10):
            ts.append(_ALPH[v % 32])
            v //= 32
        tail = []
        for b in rnd[:6]:
            tail.append(_ALPH[b % 32])
        return prefix + "".join(ts) + "".join(tail)

    def _pick_active_session(sessions):
        for s in sessions:
            if s.get("status") == "active":
                dbp = s.get("default_base_path")
                if dbp is None or (isinstance(dbp, str) and os.path.isabs(dbp)):
                    return s
        return None

    def _new_session(sessions):
        now = _now()
        s = {
            "id": _ulid("fs_sess_"),
            "client_name": None,
            "default_base_path": None,
            "default_base_path_set_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "ended_at": None,
        }
        sessions.append(s)
        return s

    def _resolve_path(session, p_in):
        if not isinstance(p_in, str) or not p_in.strip():
            return None, "VALIDATION_ERROR", "`path` is required and must be a non-empty string."
        p_in = p_in.strip()
        base = session.get("default_base_path")
        if os.path.isabs(p_in):
            resolved = os.path.normpath(p_in)
        else:
            if base is None:
                return None, "VALIDATION_ERROR", "Relative path requires session default_base_path; none set for session.", "INVALID_PATH"
            if not isinstance(base, str) or not os.path.isabs(base):
                return None, "VALIDATION_ERROR", "Session default_base_path is invalid.", "INVALID_PATH"
            resolved = os.path.normpath(os.path.join(base, p_in))
        if not os.path.isabs(resolved):
            return None, "VALIDATION_ERROR", "Resolved path must be absolute.", "INVALID_PATH"
        if isinstance(base, str) and os.path.isabs(base):
            try:
                if os.path.commonpath([os.path.normpath(base), os.path.normpath(resolved)]) != os.path.normpath(base):
                    return None, "UNAUTHORIZED", "Path is outside the session default base path.", "FORBIDDEN"
            except Exception:
                return None, "UNAUTHORIZED", "Path is outside the session default base path.", "FORBIDDEN"
        return resolved, None, None, None

    def _op_append(ops, op):
        ops.append(op)
        _save("filesystem_operations.json", ops)

    def _op_update(ops, op_id, **fields):
        now = _now()
        for r in ops:
            if r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = now
                _save("filesystem_operations.json", ops)
                return r
        return None

    # defaults/bounds
    if recursive is None:
        recursive = False
    if not isinstance(recursive, bool):
        return _err("VALIDATION_ERROR", "`recursive` must be a boolean when provided.")
    if maxEntries is None:
        maxEntries = 50
    if not isinstance(maxEntries, int) or maxEntries < 1:
        return _err("VALIDATION_ERROR", "`maxEntries` must be a positive integer when provided.")
    hard_cap = 1000
    if maxEntries > hard_cap:
        maxEntries = hard_cap

    now = _now()
    sessions = _load("sessions.json")
    ops = _load("filesystem_operations.json")
    nodes = _load("filesystem_nodes.json")

    sess = _pick_active_session(sessions)
    if sess is None or sess.get("status") == "ended":
        sess = _new_session(sessions)
        _save("sessions.json", sessions)

    resolved, vcode, vmsg, tool_error_code = _resolve_path(sess, path)

    op_id = _ulid("fs_op_")
    op = {
        "id": op_id,
        "session_id": sess["id"],
        "tool_name": "list_files",
        "status": "received",
        "parameters": {"path": path, "recursive": recursive, "maxEntries": maxEntries},
        "resolved_base_path": sess.get("default_base_path"),
        "source_path_input": path,
        "source_path_resolved": resolved,
        "destination_path_input": None,
        "destination_path_resolved": None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    _op_append(ops, op)
    _op_update(ops, op_id, status="running", started_at=_now())

    if vcode:
        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code=tool_error_code or vcode, error_message=vmsg)
        return _err(vcode, vmsg, operation_id=op_id, resolved_path=resolved)

    try:
        if not os.path.exists(resolved):
            # Reads with no matches should return empty data rather than error? For list_files, tool says lists within directory:
            # Real behavior: NOT_FOUND if directory doesn't exist. Keep NOT_FOUND.
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_FOUND", error_message="Resolved path does not exist.")
            return _err("NOT_FOUND", "Resolved path does not exist", operation_id=op_id, resolved_path=resolved)
        if not os.path.isdir(resolved):
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_A_DIRECTORY", error_message="Resolved path is not a directory.")
            return _err("CONFLICT", "Resolved path is not a directory.", operation_id=op_id, resolved_path=resolved)

        entries = []

        def add_entry(abs_path, rel_name):
            nonlocal entries
            try:
                st = os.stat(abs_path)
                is_dir = os.path.isdir(abs_path)
                entries.append(
                    {
                        "path": rel_name,
                        "type": "directory" if is_dir else "file",
                        "size_bytes": None if is_dir else int(getattr(st, "st_size", 0)),
                    }
                )
            except Exception:
                # skip unreadable entries
                return

        if recursive:
            for root, dirs, files in os.walk(resolved):
                # deterministic-ish order
                dirs.sort()
                files.sort()
                for d in dirs:
                    if len(entries) >= maxEntries:
                        break
                    abs_p = os.path.join(root, d)
                    rel = os.path.relpath(abs_p, resolved)
                    add_entry(abs_p, rel)
                if len(entries) >= maxEntries:
                    break
                for fn in files:
                    if len(entries) >= maxEntries:
                        break
                    abs_p = os.path.join(root, fn)
                    rel = os.path.relpath(abs_p, resolved)
                    add_entry(abs_p, rel)
                if len(entries) >= maxEntries:
                    break
        else:
            names = []
            try:
                names = os.listdir(resolved)
            except Exception:
                names = []
            names.sort()
            for name in names:
                if len(entries) >= maxEntries:
                    break
                abs_p = os.path.join(resolved, name)
                add_entry(abs_p, name)

        # upsert directory node in catalog
        dir_node = None
        for r in nodes:
            if r.get("canonical_path") == resolved:
                dir_node = r
                break
        if dir_node is None:
            dir_node = {
                "id": _ulid("fs_node_"),
                "canonical_path": resolved,
                "node_type": "directory",
                "exists_flag": True,
                "size_bytes": None,
                "content_hash_sha256": None,
                "last_seen_at": _now(),
                "status": "present",
                "created_at": _now(),
                "updated_at": _now(),
            }
            nodes.append(dir_node)
        else:
            dir_node["node_type"] = "directory"
            dir_node["exists_flag"] = True
            dir_node["size_bytes"] = None
            dir_node["content_hash_sha256"] = None
            dir_node["last_seen_at"] = _now()
            dir_node["status"] = "present"
            dir_node["updated_at"] = _now()
        _save("filesystem_nodes.json", nodes)

        fin = _now()
        _op_update(
            ops,
            op_id,
            status="succeeded",
            finished_at=fin,
            node_id=dir_node.get("id"),
            result_summary={"entries_returned": len(entries)},
        )

        return {"resolved_path": resolved, "entries": entries, "operation_id": op_id, "entries_returned": len(entries)}
    except Exception as e:
        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code="FAILED", error_message=str(e))
        return _err("CONFLICT", "Unable to list directory.", operation_id=op_id, resolved_path=resolved)

