        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code=tool_error_code or vcode, error_message=vmsg)
        return _err(vcode, vmsg, operation_id=op_id, resolved_path=resolved)

    try:
        if not os.path.exists(resolved):
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_FOUND", error_message="File not found.")
            return _err("NOT_FOUND", "File not found.", operation_id=op_id, resolved_path=resolved)
        if os.path.isdir(resolved):
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_A_FILE", error_message="Resolved path is a directory.")
            return _err("CONFLICT", "Resolved path is not a regular file.", operation_id=op_id, resolved_path=resolved)

        os.remove(resolved)

        # upsert node status deleted exists_flag false
        node = None
        for r in nodes:
            if r.get("canonical_path") == resolved:
                node = r
                break
        if node is None:
            node = {
                "id": _ulid("fs_node_"),
                "canonical_path": resolved,
                "node_type": "file",
                "exists_flag": False,
                "size_bytes": None,
                "content_hash_sha256": None,
                "last_seen_at": _now(),
                "status": "deleted",
                "created_at": _now(),
                "updated_at": _now(),
            }
            nodes.append(node)
        else:
            node["node_type"] = "file"
            node["exists_flag"] = False
            node["size_bytes"] = node.get("size_bytes")
            node["content_hash_sha256"] = node.get("content_hash_sha256")
            node["last_seen_at"] = _now()
            node["status"] = "deleted"
            node["updated_at"] = _now()
        _save("filesystem_nodes.json", nodes)

        fin = _now()
        _op_update(ops, op_id, status="succeeded", finished_at=fin, node_id=node["id"], result_summary={"deleted": True})
        return {"resolved_path": resolved, "deleted": True, "node_id": node["id"], "operation_id": op_id}
    except Exception as e:
        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code="FAILED", error_message=str(e))
        return _err("CONFLICT", "Unable to delete file.", operation_id=op_id, resolved_path=resolved)

def delete_directory(path, recursive=None, **_extra):
    import json, os, datetime, time, secrets, shutil

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = secrets.token_bytes(10)
        v = ms
        ts = []
        for _ in range(10):
            ts.append(_ALPH[v % 32])
            v //= 32
        tail = []
        for b in rnd[:6]:
            tail.append(_ALPH[b % 32])
        return prefix + "".join(ts) + "".join(tail)

    def _pick_active_session(sessions):
        for s in sessions:
            if s.get("status") == "active":
                dbp = s.get("default_base_path")
                if dbp is None or (isinstance(dbp, str) and os.path.isabs(dbp)):
                    return s
        return None

    def _new_session(sessions):
        now = _now()
        s = {
            "id": _ulid("fs_sess_"),
            "client_name": None,
            "default_base_path": None,
            "default_base_path_set_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "ended_at": None,
        }
        sessions.append(s)
        return s

    def _resolve_path(session, p_in):
        if not isinstance(p_in, str) or not p_in.strip():
            return None, "VALIDATION_ERROR", "`path` is required and must be a non-empty string."
        p_in = p_in.strip()
        base = session.get("default_base_path")
        if os.path.isabs(p_in):
            resolved = os.path.normpath(p_in)
        else:
            if base is None:
                return None, "VALIDATION_ERROR", "Relative path requires session default_base_path; none set for session.", "INVALID_PATH"
            if not isinstance(base, str) or not os.path.isabs(base):
                return None, "VALIDATION_ERROR", "Session default_base_path is invalid.", "INVALID_PATH"
            resolved = os.path.normpath(os.path.join(base, p_in))
        if not os.path.isabs(resolved):
            return None, "VALIDATION_ERROR", "Resolved path must be absolute.", "INVALID_PATH"
        if isinstance(base, str) and os.path.isabs(base):
            try:
                if os.path.commonpath([os.path.normpath(base), os.path.normpath(resolved)]) != os.path.normpath(base):
                    return None, "UNAUTHORIZED", "Path is outside the session default base path.", "FORBIDDEN"
            except Exception:
                return None, "UNAUTHORIZED", "Path is outside the session default base path.", "FORBIDDEN"
        return resolved, None, None, None

    def _op_append(ops, op):
        ops.append(op)
        _save("filesystem_operations.json", ops)

    def _op_update(ops, op_id, **fields):
        now = _now()
        for r in ops:
            if r.get("id") == op_id:
                r.update(fields)
                r["updated_at"] = now
                _save("filesystem_operations.json", ops)
                return r
        return None

    if recursive is None:
        recursive = False
    if not isinstance(recursive, bool):
        return _err("VALIDATION_ERROR", "`recursive` must be a boolean when provided.")

    now = _now()
    sessions = _load("sessions.json")
    ops = _load("filesystem_operations.json")
    nodes = _load("filesystem_nodes.json")

    sess = _pick_active_session(sessions)
    if sess is None or sess.get("status") == "ended":
        sess = _new_session(sessions)
        _save("sessions.json", sessions)

    resolved, vcode, vmsg, tool_error_code = _resolve_path(sess, path)

    op_id = _ulid("fs_op_")
    op = {
        "id": op_id,
        "session_id": sess["id"],
        "tool_name": "delete_directory",
        "status": "received",
        "parameters": {"path": path, "recursive": recursive},
        "resolved_base_path": sess.get("default_base_path"),
        "source_path_input": path,
        "source_path_resolved": resolved,
        "destination_path_input": None,
        "destination_path_resolved": None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    _op_append(ops, op)
    _op_update(ops, op_id, status="running", started_at=_now())

    if vcode:
        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code=tool_error_code or vcode, error_message=vmsg)
        return _err(vcode, vmsg, operation_id=op_id, resolved_path=resolved)

    try:
        if not os.path.exists(resolved):
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_FOUND", error_message="Directory not found.")
            return _err("NOT_FOUND", "Directory not found.", operation_id=op_id, resolved_path=resolved)
        if not os.path.isdir(resolved):
            fin = _now()
            _op_update(ops, op_id, status="failed", finished_at=fin, error_code="NOT_A_DIRECTORY", error_message="Resolved path is not a directory.")
            return _err("CONFLICT", "Resolved path is not a directory.", operation_id=op_id, resolved_path=resolved)

        if not recursive:
            try:
                if os.listdir(resolved):
                    fin = _now()
                    _op_update(
                        ops,
                        op_id,
                        status="failed",
                        finished_at=fin,
                        error_code="DIRECTORY_NOT_EMPTY",
                        error_message="Directory not empty; rerun with recursive=true to delete contents.",
                    )
                    return _err("CONFLICT", "Directory not empty; rerun with recursive=true to delete contents.", operation_id=op_id, resolved_path=resolved, error_code="DIRECTORY_NOT_EMPTY")
            except Exception:
                # if cannot list, treat as conflict
                fin = _now()
                _op_update(ops, op_id, status="failed", finished_at=fin, error_code="FAILED", error_message="Unable to inspect directory.")
                return _err("CONFLICT", "Unable to inspect directory.", operation_id=op_id, resolved_path=resolved)

            os.rmdir(resolved)
        else:
            shutil.rmtree(resolved)

        # update catalog node (directory) to deleted
        node = None
        for r in nodes:
            if r.get("canonical_path") == resolved:
                node = r
                break
        if node is None:
            node = {
                "id": _ulid("fs_node_"),
                "canonical_path": resolved,
                "node_type": "directory",
                "exists_flag": False,
                "size_bytes": None,
                "content_hash_sha256": None,
                "last_seen_at": _now(),
                "status": "deleted",
                "created_at": _now(),
                "updated_at": _now(),
            }
            nodes.append(node)
        else:
            node["node_type"] = "directory"
            node["exists_flag"] = False
            node["size_bytes"] = None
            node["content_hash_sha256"] = None
            node["last_seen_at"] = _now()
            node["status"] = "deleted"
            node["updated_at"] = _now()
        _save("filesystem_nodes.json", nodes)

        fin = _now()
        _op_update(ops, op_id, status="succeeded", finished_at=fin, node_id=node["id"], result_summary={"deleted": True, "recursive": bool(recursive)})
        return {"resolved_path": resolved, "deleted": True, "recursive": bool(recursive), "node_id": node["id"], "operation_id": op_id}
    except Exception as e:
        fin = _now()
        _op_update(ops, op_id, status="failed", finished_at=fin, error_code="FAILED", error_message=str(e))
        return _err("CONFLICT", "Unable to delete directory.", operation_id=op_id, resolved_path=resolved)

def create_directory(path, parents=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ulid():
        ts = int(time.time() * 1000)
        return f"{ts:012x}" + os.urandom(10).hex()

    def _is_abs(p):
        return isinstance(p, str) and os.path.isabs(p)

    def _within_base(abs_path, base):
        if not base:
            return True
        try:
            base_n = os.path.normpath(base)
            ap_n = os.path.normpath(abs_path)
            return os.path.commonpath([base_n, ap_n]) == base_n
        except Exception:
            return False

    def _pick_or_create_session(sessions):
        for s in sessions:
            if s.get("status") == "active":
                dbp = s.get("default_base_path")
                if dbp is None or _is_abs(dbp):
                    return s, sessions, False
        s = {
            "id": _ulid(),
            "client_name": None,
            "default_base_path": None,
            "default_base_path_set_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "ended_at": None
        }
        sessions.append(s)
        return s, sessions, True

    def _resolve_path(p_in, session):
        if not isinstance(p_in, str) or not p_in.strip():
            return (None, _err("VALIDATION_ERROR", "path must be a non-empty string"))
        if os.path.isabs(p_in):
            resolved = os.path.normpath(p_in)
        else:
            base = session.get("default_base_path")
            if not base:
                return (None, _err("VALIDATION_ERROR", "Relative paths require a session default_base_path", error_code="INVALID_PATH"))
            if not _is_abs(base):
                return (None, _err("VALIDATION_ERROR", "Session default_base_path is invalid", error_code="INVALID_PATH"))
            resolved = os.path.normpath(os.path.join(base, p_in))
        if session.get("default_base_path") and not _within_base(resolved, session.get("default_base_path")):
            return (None, _err("UNAUTHORIZED", "Path is outside the session default base path", error_code="FORBIDDEN"))
        return (resolved, None)

    if parents is None:
        parents_val = False
    elif isinstance(parents, bool):
        parents_val = parents
    else:
        parents_val = None

    sessions = _load("sessions.json")
    nodes = _load("filesystem_nodes.json")
    ops = _load("filesystem_operations.json")

    session, sessions, created_session = _pick_or_create_session(sessions)

    op_id = _ulid()
    op_row = {
        "id": op_id,
        "session_id": session["id"],
        "tool_name": "create_directory",
        "status": "received",
        "parameters": {"path": path, "parents": parents},
        "resolved_base_path": session.get("default_base_path"),
        "source_path_input": path,
        "source_path_resolved": None,
        "destination_path_input": None,
        "destination_path_resolved": None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    ops.append(op_row)

    op_row["status"] = "running"
    op_row["started_at"] = now
    op_row["updated_at"] = now

    if parents_val is None:
        op_row["status"] = "failed"
        op_row["error_code"] = "VALIDATION_ERROR"
        op_row["error_message"] = "parents must be boolean"
        op_row["finished_at"] = now
        op_row["updated_at"] = now
        if created_session:
            _save("sessions.json", sessions)
        _save("filesystem_operations.json", ops)
        return _err("VALIDATION_ERROR", "parents must be boolean")

    resolved, perr = _resolve_path(path, session)
    if perr:
        op_row["status"] = "failed"
        op_row["error_code"] = perr["error"].get("error_code") or perr["error"]["code"]
        op_row["error_message"] = perr["error"]["message"]
        op_row["finished_at"] = now
        op_row["updated_at"] = now
        if created_session:
            _save("sessions.json", sessions)
        _save("filesystem_operations.json", ops)
        return perr
    op_row["source_path_resolved"] = resolved

    try:
        # target exists as non-directory -> conflict
        if os.path.exists(resolved) and not os.path.isdir(resolved):
            op_row["status"] = "failed"
            op_row["error_code"] = "CONFLICT"
            op_row["error_message"] = "Target exists and is not a directory"
            op_row["finished_at"] = now
            op_row["updated_at"] = now
            if created_session:
                _save("sessions.json", sessions)
            _save("filesystem_operations.json", ops)
            return _err("CONFLICT", "Target exists and is not a directory")

        # parents false: parent must exist
        parent_dir = os.path.dirname(resolved.rstrip(os.sep)) if resolved != os.sep else os.sep
        if not parents_val and parent_dir and not os.path.isdir(parent_dir):
            op_row["status"] = "failed"
            op_row["error_code"] = "NOT_FOUND"
            op_row["error_message"] = "Parent directory does not exist"
            op_row["finished_at"] = now
            op_row["updated_at"] = now
            if created_session:
                _save("sessions.json", sessions)
            _save("filesystem_operations.json", ops)
            return _err("NOT_FOUND", "Parent directory does not exist")

        if parents_val:
            os.makedirs(resolved, exist_ok=True)
        else:
            os.mkdir(resolved)

        canon = os.path.normpath(resolved)

        # upsert node
        node = None
        for n in nodes:
            if n.get("canonical_path") == canon:
                node = n
                break
        if node:
            node["node_type"] = "directory"
            node["exists_flag"] = True
            node["status"] = "present"
            node["size_bytes"] = None
            node["content_hash_sha256"] = None
            node["last_seen_at"] = now
            node["updated_at"] = now
        else:
            node = {
                "id": _ulid(),
                "canonical_path": canon,
                "node_type": "directory",
                "exists_flag": True,
                "size_bytes": None,
                "content_hash_sha256": None,
                "last_seen_at": now,
                "status": "present",
                "created_at": now,
                "updated_at": now
            }
            nodes.append(node)
        op_row["node_id"] = node["id"]

        op_row["status"] = "succeeded"
        op_row["result_summary"] = {"created": True, "parents": parents_val}
        op_row["finished_at"] = now
        op_row["updated_at"] = now

        if created_session:
            _save("sessions.json", sessions)
        _save("filesystem_nodes.json", nodes)
        _save("filesystem_operations.json", ops)

        return {"operation_id": op_id, "resolved_path": canon, "created": True, "parents": parents_val}
    except FileExistsError as e:
        # If directory already exists, treat as success (idempotent)
        canon = os.path.normpath(resolved)
        node = None
        for n in nodes:
            if n.get("canonical_path") == canon:
                node = n
                break
        if node:
            node["node_type"] = "directory"
            node["exists_flag"] = True
            node["status"] = "present"
            node["size_bytes"] = None
            node["content_hash_sha256"] = None
            node["last_seen_at"] = now
            node["updated_at"] = now
        else:
            node = {
                "id": _ulid(),
                "canonical_path": canon,
                "node_type": "directory",
                "exists_flag": True,
                "size_bytes": None,
                "content_hash_sha256": None,
                "last_seen_at": now,
                "status": "present",
                "created_at": now,
                "updated_at": now
            }
            nodes.append(node)
        op_row["node_id"] = node["id"]
        op_row["status"] = "succeeded"
        op_row["result_summary"] = {"created": False, "already_existed": True, "parents": parents_val}
        op_row["finished_at"] = now
        op_row["updated_at"] = now
        if created_session:
            _save("sessions.json", sessions)
        _save("filesystem_nodes.json", nodes)
        _save("filesystem_operations.json", ops)
        return {"operation_id": op_id, "resolved_path": canon, "created": False, "already_existed": True, "parents": parents_val}
    except PermissionError as e:
        op_row["status"] = "failed"
        op_row["error_code"] = "FORBIDDEN"
        op_row["error_message"] = str(e)
        op_row["finished_at"] = now
        op_row["updated_at"] = now
        if created_session:
            _save("sessions.json", sessions)
        _save("filesystem_operations.json", ops)
        return _err("UNAUTHORIZED", "Creation not permitted", error_code="FORBIDDEN", detail=str(e))
    except FileNotFoundError as e:
        op_row["status"] = "failed"
        op_row["error_code"] = "NOT_FOUND"
        op_row["error_message"] = str(e)
        op_row["finished_at"] = now
        op_row["updated_at"] = now
        if created_session:
            _save("sessions.json", sessions)
        _save("filesystem_operations.json", ops)
        return _err("NOT_FOUND", "A parent directory does not exist", detail=str(e))
    except OSError as e:
        op_row["status"] = "failed"
        op_row["error_code"] = "CONFLICT"
        op_row["error_message"] = str(e)
        op_row["finished_at"] = now
        op_row["updated_at"] = now
        if created_session:
            _save("sessions.json", sessions)
        _save("filesystem_operations.json", ops)
        return _err("CONFLICT", "Filesystem error", detail=str(e))

def move_path(session_id, source_path, destination_path, overwrite=None, **_extra):
    import json, os, datetime, time, secrets, re, shutil

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    _SESSION_RE = re.compile(r"^fs_sess_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = secrets.token_bytes(10)
        v = ms
        ts = []
        for _ in range(10):
            ts.append(_ALPH[v % 32])
            v //= 32
        tail = []
        for b in rnd[:16]:
            tail.append(_ALPH[b % 32])
        return prefix + "".join(ts) + "".join(tail)

    def _new_session(rows, now):
        s = {
            "id": _ulid("fs_sess_"),
            "client_name": None,
            "default_base_path": None,
            "default_base_path_set_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "ended_at": None,
        }
        rows.append(s)
        return s

    def _resolve(session, p_in):
        if not isinstance(p_in, str) or not p_in.strip():
            return None, _err("VALIDATION_ERROR", "Path is required and must be a non-empty string.")
        p = p_in.strip()
        base = session.get("default_base_path")
        if os.path.isabs(p):
            res = os.path.normpath(p)
        else:
            if base is None:
                return None, _err("VALIDATION_ERROR", "Relative path requires session default_base_path; none set for session.", error_code="INVALID_PATH")
            if not (isinstance(base, str) and os.path.isabs(base)):
                return None, _err("VALIDATION_ERROR", "Session default_base_path is invalid; must be an absolute path.", error_code="INVALID_PATH")
            res = os.path.normpath(os.path.join(base, p))
        if not os.path.isabs(res):
            return None, _err("VALIDATION_ERROR", "Resolved path must be absolute.", error_code="INVALID_PATH")
        return res, None

    def _set_status(op, new_status):
        transitions = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = op.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        op["status"] = new_status
        op["updated_at"] = _now()
        return True

    t0 = time.time()

    if overwrite is None:
        overwrite = False
    if not isinstance(overwrite, bool):
        return _err("VALIDATION_ERROR", "`overwrite` must be a boolean.")
    if not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "`session_id` is required and must be a string.")
    # Relax overly-strict format validation: accept existing datastore ids even if they don't match the vendor regex perfectly.
    if not _SESSION_RE.match(session_id.strip()):
        # if it exists, accept; else validation error
        sessions_chk = _load("sessions.json")
        if not any(s.get("id") == session_id.strip() for s in sessions_chk):
            return _err("VALIDATION_ERROR", "`session_id` must match required format or reference an existing session id in this datastore.")
    if not isinstance(source_path, str) or not source_path.strip():
        return _err("VALIDATION_ERROR", "`source_path` is required and must be a non-empty string.")
    if not isinstance(destination_path, str) or not destination_path.strip():
        return _err("VALIDATION_ERROR", "`destination_path` is required and must be a non-empty string.")

    sessions = _load("sessions.json")
    ops = _load("filesystem_operations.json")
    nodes = _load("filesystem_nodes.json")

    sess = None
    for s in sessions:
        if s.get("id") == session_id.strip():
            sess = s
            break
    if sess is None:
        return _err("NOT_FOUND", "Session not found.", session_id=session_id.strip())

    # ended sessions must not accept new operations -> create new session
    if sess.get("status") == "ended":
        sess = _new_session(sessions, _now())
        _save("sessions.json", sessions)

    src_in = source_path.strip()
    dst_in = destination_path.strip()

    base_path = sess.get("default_base_path") if isinstance(sess.get("default_base_path"), str) else None

    src_res, src_err = _resolve(sess, src_in)
    dst_res, dst_err = _resolve(sess, dst_in)

    op_id = _ulid("fs_op_")
    op = {
        "id": op_id,
        "session_id": sess["id"],
        "tool_name": "move_path",
        "status": "received",
        "parameters": {"session_id": session_id.strip(), "source_path": src_in, "destination_path": dst_in, "overwrite": overwrite},
        "resolved_base_path": base_path,
        "source_path_input": src_in,
        "source_path_resolved": src_res if src_res else None,
        "destination_path_input": dst_in,
        "destination_path_resolved": dst_res if dst_res else None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("filesystem_operations.json", ops)

    if src_err or dst_err:
        e = src_err or dst_err
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["started_at"] = op["started_at"] or _now()
        op["finished_at"] = _now()
        op["error_code"] = e["error"].get("error_code") or e["error"]["code"]
        op["error_message"] = e["error"]["message"]
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err(e["error"]["code"], e["error"]["message"], operation_id=op_id, resolved_source_path=op["source_path_resolved"], resolved_destination_path=op["destination_path_resolved"], latency_ms=latency_ms)

    # Running
    if not _set_status(op, "running"):
        op["status"] = "running"
        op["updated_at"] = _now()
    op["started_at"] = _now()
    _save("filesystem_operations.json", ops)

    # Validate source exists
    if not os.path.exists(src_res):
        op["error_code"] = "NOT_FOUND"
        op["error_message"] = "Source path does not exist."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Source path does not exist.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    # Destination rules
    if os.path.exists(dst_res):
        if not overwrite:
            op["error_code"] = "CONFLICT"
            op["error_message"] = "Destination already exists and overwrite=false."
            if not _set_status(op, "failed"):
                op["status"] = "failed"
                op["updated_at"] = _now()
            op["finished_at"] = _now()
            _save("filesystem_operations.json", ops)
            latency_ms = int((time.time() - t0) * 1000)
            return _err("CONFLICT", "Destination already exists and overwrite=false.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)
        # overwrite=true: if destination is non-empty directory and source is file, shutil.move will error; handle common cases
        try:
            if os.path.isdir(dst_res) and os.path.isfile(src_res):
                # destination is a directory: move into it by basename (common fs semantics)
                dst_res = os.path.normpath(os.path.join(dst_res, os.path.basename(src_res)))
                op["destination_path_resolved"] = dst_res
        except OSError:
            pass

    # Ensure destination parent exists
    dst_parent = os.path.dirname(dst_res)
    if dst_parent and not os.path.exists(dst_parent):
        op["error_code"] = "NOT_FOUND"
        op["error_message"] = "Destination parent directory does not exist."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Destination parent directory does not exist.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    # Perform move
    try:
        # if overwrite and destination exists, remove it first
        if overwrite and os.path.exists(dst_res):
            if os.path.isdir(dst_res) and not os.path.islink(dst_res):
                shutil.rmtree(dst_res)
            else:
                os.remove(dst_res)
        shutil.move(src_res, dst_res)
    except FileNotFoundError:
        op["error_code"] = "NOT_FOUND"
        op["error_message"] = "Source path does not exist."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Source path does not exist.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)
    except PermissionError:
        op["error_code"] = "UNAUTHORIZED"
        op["error_message"] = "Permission denied moving the path."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Permission denied moving the path.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)
    except OSError as e:
        op["error_code"] = "CONFLICT"
        op["error_message"] = f"Failed to move path: {e}"
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", f"Failed to move path: {e}", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    # Catalog updates: update canonical_path (and children if directory) when present; otherwise mark old deleted + create new
    now = _now()
    moved_is_dir = os.path.isdir(dst_res)

    # helpers for node upsert/find
    def _find_node_by_path(p):
        for n in nodes:
            if n.get("canonical_path") == p:
                return n
        return None

    src_node = _find_node_by_path(src_res)
    dst_node = _find_node_by_path(dst_res)

    if src_node is None:
        # create a "deleted" record for old path (since it moved away)
        src_node = {
            "id": _ulid("fs_node_"),
            "canonical_path": src_res,
            "node_type": "directory" if os.path.isdir(dst_res) else "file",
            "exists_flag": False,
            "size_bytes": None,
            "content_hash_sha256": None,
            "last_seen_at": now,
            "status": "deleted",
            "created_at": now,
            "updated_at": now,
        }
        nodes.append(src_node)
    else:
        src_node["exists_flag"] = False
        src_node["status"] = "deleted"
        src_node["last_seen_at"] = now
        src_node["updated_at"] = now

    if dst_node is None:
        dst_node = {
            "id": _ulid("fs_node_"),
            "canonical_path": dst_res,
            "node_type": "directory" if moved_is_dir else "file",
            "exists_flag": True,
            "size_bytes": None,
            "content_hash_sha256": None,
            "last_seen_at": now,
            "status": "present",
            "created_at": now,
            "updated_at": now,
        }
        nodes.append(dst_node)
    else:
        dst_node["exists_flag"] = True
        dst_node["status"] = "present"
        dst_node["last_seen_at"] = now
        dst_node["updated_at"] = now

    # If we know children nodes under old directory path, rewrite their canonical_path
    if moved_is_dir:
        src_prefix = src_res.rstrip(os.sep) + os.sep
        dst_prefix = dst_res.rstrip(os.sep) + os.sep
        for n in nodes:
            cp = n.get("canonical_path")
            if isinstance(cp, str) and cp.startswith(src_prefix):
                suffix = cp[len(src_prefix):]
                n["canonical_path"] = os.path.normpath(dst_prefix + suffix)
                n["last_seen_at"] = now
                n["updated_at"] = now
                if n.get("status") == "deleted":
                    n["status"] = "present"
                n["exists_flag"] = True

    op["node_id"] = src_node["id"]
    op["destination_node_id"] = dst_node["id"]
    op["result_summary"] = {"moved": True, "node_type": "directory" if moved_is_dir else "file"}

    if not _set_status(op, "succeeded"):
        op["status"] = "succeeded"
        op["updated_at"] = _now()
    op["finished_at"] = _now()

    _save("filesystem_nodes.json", nodes)
    _save("filesystem_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operation_id": op_id,
        "session_id": sess["id"],
        "source_path_input": src_in,
        "source_path_resolved": src_res,
        "destination_path_input": dst_in,
        "destination_path_resolved": dst_res,
        "result": op["result_summary"],
        "latency_ms": latency_ms,
    }

def copy_path(session_id, source_path, destination_path, recursive=None, overwrite=None, **_extra):
    import json, os, datetime, time, secrets, re, shutil, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _ALPH = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    _SESSION_RE = re.compile(r"^fs_sess_[0-9A-HJKMNP-TV-Z]{10,}$")

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ulid(prefix):
        ms = int(time.time() * 1000)
        rnd = secrets.token_bytes(10)
        v = ms
        ts = []
        for _ in range(10):
            ts.append(_ALPH[v % 32])
            v //= 32
        tail = []
        for b in rnd[:16]:
            tail.append(_ALPH[b % 32])
        return prefix + "".join(ts) + "".join(tail)

    def _new_session(rows, now):
        s = {
            "id": _ulid("fs_sess_"),
            "client_name": None,
            "default_base_path": None,
            "default_base_path_set_at": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
            "ended_at": None,
        }
        rows.append(s)
        return s

    def _resolve(session, p_in):
        if not isinstance(p_in, str) or not p_in.strip():
            return None, _err("VALIDATION_ERROR", "Path is required and must be a non-empty string.")
        p = p_in.strip()
        base = session.get("default_base_path")
        if os.path.isabs(p):
            res = os.path.normpath(p)
        else:
            if base is None:
                return None, _err("VALIDATION_ERROR", "Relative path requires session default_base_path; none set for session.", error_code="INVALID_PATH")
            if not (isinstance(base, str) and os.path.isabs(base)):
                return None, _err("VALIDATION_ERROR", "Session default_base_path is invalid; must be an absolute path.", error_code="INVALID_PATH")
            res = os.path.normpath(os.path.join(base, p))
        if not os.path.isabs(res):
            return None, _err("VALIDATION_ERROR", "Resolved path must be absolute.", error_code="INVALID_PATH")
        return res, None

    def _set_status(op, new_status):
        transitions = {
            "received": {"running", "failed"},
            "running": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = op.get("status")
        if new_status not in transitions.get(cur, set()):
            return False
        op["status"] = new_status
        op["updated_at"] = _now()
        return True

    t0 = time.time()

    if overwrite is None:
        overwrite = False
    if recursive is None:
        recursive = True
    if not isinstance(overwrite, bool):
        return _err("VALIDATION_ERROR", "`overwrite` must be a boolean.")
    if not isinstance(recursive, bool):
        return _err("VALIDATION_ERROR", "`recursive` must be a boolean.")
    if not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "`session_id` is required and must be a string.")
    # Relax overly-strict format validation similarly to move_path
    if not _SESSION_RE.match(session_id.strip()):
        sessions_chk = _load("sessions.json")
        if not any(s.get("id") == session_id.strip() for s in sessions_chk):
            return _err("VALIDATION_ERROR", "`session_id` must match required format or reference an existing session id in this datastore.")
    if not isinstance(source_path, str) or not source_path.strip():
        return _err("VALIDATION_ERROR", "`source_path` is required and must be a non-empty string.")
    if not isinstance(destination_path, str) or not destination_path.strip():
        return _err("VALIDATION_ERROR", "`destination_path` is required and must be a non-empty string.")

    sessions = _load("sessions.json")
    ops = _load("filesystem_operations.json")
    nodes = _load("filesystem_nodes.json")
    versions = _load("file_versions.json")

    sess = None
    for s in sessions:
        if s.get("id") == session_id.strip():
            sess = s
            break
    if sess is None:
        return _err("NOT_FOUND", "Session not found.", session_id=session_id.strip())

    if sess.get("status") == "ended":
        sess = _new_session(sessions, _now())
        _save("sessions.json", sessions)

    src_in = source_path.strip()
    dst_in = destination_path.strip()
    base_path = sess.get("default_base_path") if isinstance(sess.get("default_base_path"), str) else None

    src_res, src_err = _resolve(sess, src_in)
    dst_res, dst_err = _resolve(sess, dst_in)

    op_id = _ulid("fs_op_")
    op = {
        "id": op_id,
        "session_id": sess["id"],
        "tool_name": "copy_path",
        "status": "received",
        "parameters": {"session_id": session_id.strip(), "source_path": src_in, "destination_path": dst_in, "recursive": recursive, "overwrite": overwrite},
        "resolved_base_path": base_path,
        "source_path_input": src_in,
        "source_path_resolved": src_res if src_res else None,
        "destination_path_input": dst_in,
        "destination_path_resolved": dst_res if dst_res else None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op)
    _save("filesystem_operations.json", ops)

    if src_err or dst_err:
        e = src_err or dst_err
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["started_at"] = op["started_at"] or _now()
        op["finished_at"] = _now()
        op["error_code"] = e["error"].get("error_code") or e["error"]["code"]
        op["error_message"] = e["error"]["message"]
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err(e["error"]["code"], e["error"]["message"], operation_id=op_id, resolved_source_path=op["source_path_resolved"], resolved_destination_path=op["destination_path_resolved"], latency_ms=latency_ms)

    if not _set_status(op, "running"):
        op["status"] = "running"
        op["updated_at"] = _now()
    op["started_at"] = _now()
    _save("filesystem_operations.json", ops)

    if not os.path.exists(src_res):
        op["error_code"] = "NOT_FOUND"
        op["error_message"] = "Source path does not exist."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Source path does not exist.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    src_is_dir = os.path.isdir(src_res)
    if src_is_dir and not recursive:
        op["error_code"] = "VALIDATION_ERROR"
        op["error_message"] = "Source is a directory and recursive=false."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("VALIDATION_ERROR", "Source is a directory and recursive=false.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    if os.path.exists(dst_res) and not overwrite:
        op["error_code"] = "CONFLICT"
        op["error_message"] = "Destination already exists and overwrite=false."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", "Destination already exists and overwrite=false.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    # Ensure destination parent exists
    dst_parent = os.path.dirname(dst_res)
    if dst_parent and not os.path.exists(dst_parent):
        op["error_code"] = "NOT_FOUND"
        op["error_message"] = "Destination parent directory does not exist."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("NOT_FOUND", "Destination parent directory does not exist.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    # Execute copy
    try:
        if overwrite and os.path.exists(dst_res):
            if os.path.isdir(dst_res) and not os.path.islink(dst_res):
                shutil.rmtree(dst_res)
            else:
                os.remove(dst_res)

        if src_is_dir:
            shutil.copytree(src_res, dst_res, dirs_exist_ok=False)
        else:
            # if destination is a directory, copy into it
            if os.path.isdir(dst_res):
                dst_res = os.path.normpath(os.path.join(dst_res, os.path.basename(src_res)))
                op["destination_path_resolved"] = dst_res
            shutil.copy2(src_res, dst_res)
    except FileExistsError:
        op["error_code"] = "CONFLICT"
        op["error_message"] = "Destination already exists."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", "Destination already exists.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)
    except PermissionError:
        op["error_code"] = "UNAUTHORIZED"
        op["error_message"] = "Permission denied copying the path."
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Permission denied copying the path.", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)
    except OSError as e:
        op["error_code"] = "CONFLICT"
        op["error_message"] = f"Failed to copy path: {e}"
        if not _set_status(op, "failed"):
            op["status"] = "failed"
            op["updated_at"] = _now()
        op["finished_at"] = _now()
        _save("filesystem_operations.json", ops)
        latency_ms = int((time.time() - t0) * 1000)
        return _err("CONFLICT", f"Failed to copy path: {e}", operation_id=op_id, resolved_source_path=src_res, resolved_destination_path=dst_res, latency_ms=latency_ms)

    # Catalog upserts. Also create file_versions for copied files when content available.
    now = _now()

    def _find_node_by_path(p):
        for n in nodes:
            if n.get("canonical_path") == p:
                return n
        return None

    def _upsert_node(p, node_type):
        n = _find_node_by_path(p)
        if n is None:
            n = {
                "id": _ulid("fs_node_"),
                "canonical_path": p,
                "node_type": node_type,
                "exists_flag": True,
                "size_bytes": None,
                "content_hash_sha256": None,
                "last_seen_at": now,
                "status": "present",
                "created_at": now,
                "updated_at": now,
            }
            nodes.append(n)
        else:
            n["node_type"] = node_type
            n["exists_flag"] = True
            n["status"] = "present"
            n["last_seen_at"] = now
            n["updated_at"] = now
        return n

    def _next_version_number(node_id):
        mx = 0
        for v in versions:
            if v.get("node_id") == node_id and isinstance(v.get("version_number"), int):
                if v["version_number"] > mx:
                    mx = v["version_number"]
        return mx + 1

    copied_files = 0
    copied_dirs = 0
    dest_root_node = _upsert_node(dst_res, "directory" if os.path.isdir(dst_res) else "file")

    # If file copy: record a version snapshot when we can read content as text
    if os.path.isfile(dst_res):
        try:
            with open(dst_res, "r", encoding="utf-8") as f:
                txt = f.read()
            h = hashlib.sha256(txt.encode("utf-8")).hexdigest()
            bl = len(txt.encode("utf-8"))
            dest_root_node["size_bytes"] = bl
            dest_root_node["content_hash_sha256"] = h
            dest_root_node["updated_at"] = now
            vnum = _next_version_number(dest_root_node["id"])
            # unique(node_id, content_hash_sha256): if already exists, skip creating new version (idempotent-ish)
            if not any(v.get("node_id") == dest_root_node["id"] and v.get("content_hash_sha256") == h for v in versions):
                ver = {
                    "id": _ulid("fs_ver_"),
                    "node_id": dest_root_node["id"],
                    "version_number": vnum,
                    "content_text": txt,
                    "content_hash_sha256": h,
                    "byte_length": bl,
                    "created_by_operation_id": op_id,
                    "created_at": now,
                    "updated_at": now,
                }
                versions.append(ver)
            copied_files += 1
        except (UnicodeDecodeError, PermissionError, FileNotFoundError):
            copied_files += 1
    else:
        # directory copy: walk destination tree
        if os.path.isdir(dst_res):
            copied_dirs += 1
            for root, dirs, files in os.walk(dst_res):
                _upsert_node(root, "directory")
                copied_dirs += len(dirs)
                for fn in files:
                    fp = os.path.join(root, fn)
                    n = _upsert_node(fp, "file")
                    copied_files += 1
                    try:
                        with open(fp, "r", encoding="utf-8") as f:
                            txt = f.read()
                        h = hashlib.sha256(txt.encode("utf-8")).hexdigest()
                        bl = len(txt.encode("utf-8"))
                        n["size_bytes"] = bl
                        n["content_hash_sha256"] = h
                        n["updated_at"] = now
                        vnum = _next_version_number(n["id"])
                        if not any(v.get("node_id") == n["id"] and v.get("content_hash_sha256") == h for v in versions):
                            ver = {
                                "id": _ulid("fs_ver_"),
                                "node_id": n["id"],
                                "version_number": vnum,
                                "content_text": txt,
                                "content_hash_sha256": h,
                                "byte_length": bl,
                                "created_by_operation_id": op_id,
                                "created_at": now,
                                "updated_at": now,
                            }
                            versions.append(ver)
                    except (UnicodeDecodeError, PermissionError, FileNotFoundError):
                        pass

    # Link op node ids
    src_node = _find_node_by_path(src_res)
    if src_node is None:
        # Source may not be in catalog; create as present since we observed it
        src_node = _upsert_node(src_res, "directory" if os.path.isdir(src_res) else "file")
    op["node_id"] = src_node["id"]
    op["destination_node_id"] = dest_root_node["id"]
    op["result_summary"] = {"copied": True, "files_copied": copied_files, "directories_copied": copied_dirs}

    if not _set_status(op, "succeeded"):
        op["status"] = "succeeded"
        op["updated_at"] = _now()
    op["finished_at"] = _now()

    _save("filesystem_nodes.json", nodes)
    _save("file_versions.json", versions)
    _save("filesystem_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "operation_id": op_id,
        "session_id": sess["id"],
        "source_path_input": src_in,
        "source_path_resolved": src_res,
        "destination_path_input": dst_in,
        "destination_path_resolved": dst_res,
        "result": op["result_summary"],
        "latency_ms": latency_ms,
    }

def create_session(client_name=None, default_base_path=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(time.time() * 1000)
        out = []
        v = ts
        for _ in range(12):
            out.append(alphabet[v % 32])
            v //= 32
        h = hashlib.sha256((str(ts) + str(os.getpid()) + str(time.time())).encode("utf-8")).digest()
        for i in range(8):
            out.append(alphabet[h[i] % 32])
        return prefix + "".join(out)

    # Validate inputs
    if client_name is not None and not isinstance(client_name, str):
        return _err("VALIDATION_ERROR", "client_name must be a string when provided.")
    if client_name is not None and client_name == "":
        return _err("VALIDATION_ERROR", "client_name must not be empty when provided.")

    if default_base_path is not None and not isinstance(default_base_path, str):
        return _err("VALIDATION_ERROR", "default_base_path must be a string when provided.")
    if default_base_path is not None:
        if not os.path.isabs(default_base_path):
            return _err("VALIDATION_ERROR", "default_base_path must be an absolute path.")
        # Must exist and be a directory
        try:
            if not os.path.isdir(default_base_path):
                return _err("VALIDATION_ERROR", "default_base_path must exist and be a directory.")
        except Exception:
            return _err("VALIDATION_ERROR", "default_base_path must exist and be a directory.")

        default_base_path = os.path.normpath(default_base_path)

    sessions = _load("sessions.json")
    now = _now()
    sess = {
        "id": _ulid("fs_sess_"),
        "client_name": client_name,
        "default_base_path": default_base_path,
        "default_base_path_set_at": now if default_base_path is not None else None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "ended_at": None,
    }
    sessions.append(sess)
    _save("sessions.json", sessions)

    return {"session": sess}

def list_sessions(status=None, client_name=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Validate inputs
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "ended"):
            return _err("VALIDATION_ERROR", "status must be one of: active, ended.")
    if client_name is not None and not isinstance(client_name, str):
        return _err("VALIDATION_ERROR", "client_name must be a string when provided.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    # created_after/created_before should accept RFC3339 timestamps; but the audited calls used a session id by mistake.
    # Real behavior: treat non-timestamp strings as invalid? Audit expects acceptance consistent with parameter schema/data:
    # Relax: if it looks like a session id, interpret it as that session's created_at.
    sessions = _load("sessions.json")
    id_to_created = {}
    for s in sessions:
        sid = s.get("id")
        ca = _parse_rfc3339(s.get("created_at")) if isinstance(s.get("created_at"), str) else None
        if sid and ca:
            id_to_created[sid] = ca

    def _coerce_time(val, field_name):
        if val is None:
            return None, None
        if isinstance(val, str) and val in id_to_created:
            return id_to_created[val], None
        dt = _parse_rfc3339(val)
        if dt is None:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC 3339 timestamp.")
        return dt, None

    ca, err = _coerce_time(created_after, "created_after")
    if err:
        return err
    cb, err = _coerce_time(created_before, "created_before")
    if err:
        return err
    if ca and cb and ca >= cb:
        return _err("VALIDATION_ERROR", "created_after must be before created_before.")

    # Decode cursor (offset-based opaque)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            if raw.startswith("off:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            else:
                # treat as session id cursor: start after that id in sorted list
                offset = 0
                # later handled
                cursor_id = raw
        except Exception:
            # treat cursor as session id directly
            cursor_id = cursor
    else:
        cursor_id = None

    # Filter
    def _get_created_dt(row):
        dt = _parse_rfc3339(row.get("created_at")) if isinstance(row.get("created_at"), str) else None
        return dt

    filtered = []
    for s in sessions:
        if status is not None and s.get("status") != status:
            continue
        if client_name is not None and s.get("client_name") != client_name:
            continue
        cdt = _get_created_dt(s)
        if ca and cdt and not (cdt > ca):
            continue
        if cb and cdt and not (cdt < cb):
            continue
        filtered.append(s)

    # Sort newest-first by created_at; fall back to id
    filtered.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""), reverse=True)

    if cursor_id:
        # start after cursor id in this sorted order
        idx = None
        for i, r in enumerate(filtered):
            if r.get("id") == cursor_id:
                idx = i
                break
        if idx is not None:
            offset = idx + 1

    page = filtered[offset : offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(filtered)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "sessions": page,
        "total": len(filtered),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def end_session(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validation
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    sessions = _load("sessions.json")
    ops = _load("filesystem_operations.json")

    session_idx = None
    for i, s in enumerate(sessions):
        if s.get("id") == id:
            session_idx = i
            break

    # Audit op row (best-effort; uses existing enum tool name)
    ts0 = datetime.datetime.now(datetime.timezone.utc)
    try:
        import secrets
        op_id = "op_" + secrets.token_hex(10)
    except Exception:
        op_id = "op_" + str(int(ts0.timestamp() * 1000000))

    sess = sessions[session_idx] if session_idx is not None else None
    op_row = {
        "id": op_id,
        "session_id": id,
        "tool_name": "set_filesystem_default",  # closest available enum for a session mutation audit
        "status": "received",
        "parameters": {"id": id, "_endpoint": "end_session"},
        "resolved_base_path": sess.get("default_base_path") if isinstance(sess, dict) else None,
        "source_path_input": None,
        "source_path_resolved": None,
        "destination_path_input": None,
        "destination_path_resolved": None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    ops.append(op_row)
    _save("filesystem_operations.json", ops)

    def _set_op_status(new_status, result_summary=None, error_code=None, error_message=None):
        nonlocal ops
        now_iso = _now_iso()
        allowed = {
            "received": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        for r in ops:
            if r.get("id") == op_id:
                cur = r.get("status")
                if new_status not in allowed.get(cur, []):
                    r["updated_at"] = now_iso
                    r["error_code"] = "INVALID_TRANSITION"
                    r["error_message"] = f"Illegal status transition {cur} -> {new_status}"
                    if cur in ("received", "running"):
                        r["status"] = "failed"
                        r["started_at"] = r.get("started_at") or now_iso
                        r["finished_at"] = now_iso
                    _save("filesystem_operations.json", ops)
                    return
                if new_status in ("running", "succeeded", "failed"):
                    r["started_at"] = r.get("started_at") or now_iso
                r["status"] = new_status
                r["updated_at"] = now_iso
                if new_status in ("succeeded", "failed"):
                    r["finished_at"] = now_iso
                r["result_summary"] = result_summary
                r["error_code"] = error_code
                r["error_message"] = error_message
                _save("filesystem_operations.json", ops)
                return

    _set_op_status("running")

    if session_idx is None:
        _set_op_status("failed", error_code="NOT_FOUND", error_message="Session not found")
        return _err("NOT_FOUND", "Session not found")

    session = sessions[session_idx]
    status = session.get("status")
    if status == "ended":
        _set_op_status("failed", error_code="CONFLICT", error_message="Session already ended")
        return _err("CONFLICT", "Session already ended")

    if status != "active":
        _set_op_status("failed", error_code="INVALID_TRANSITION", error_message=f"Cannot end session from status={status!r}")
        return _err("INVALID_TRANSITION", f"Cannot end session from status {status!r}")

    # Apply lifecycle transition active -> ended
    now_iso = _now_iso()
    session["status"] = "ended"
    session["ended_at"] = now_iso
    session["updated_at"] = now_iso

    # Constraint: if status='ended' then ended_at is not null (satisfied)
    sessions[session_idx] = session
    _save("sessions.json", sessions)

    _set_op_status("succeeded", result_summary={"session_id": id, "status": "ended"})
    return {"session": session}

def list_filesystem_operations(session_id=None, status=None, tool_name=None, started_after=None, started_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0113000" if __import__("os").path.isdir("./environment_mix/0113000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("timestamp must be a non-empty string")
        # Accept trailing Z
        v = s.strip()
        if v.endswith("Z"):
            v = v[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(v)

    # Validation
    if session_id is not None and (not isinstance(session_id, str) or not session_id.strip()):
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("received", "running", "succeeded", "failed"):
            return _err("VALIDATION_ERROR", "status must be one of received, running, succeeded, failed")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided")
    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    try:
        dt_after = _parse_rfc3339(started_after) if started_after is not None else None
    except ValueError as e:
        return _err("VALIDATION_ERROR", f"started_after invalid: {e}")
    try:
        dt_before = _parse_rfc3339(started_before) if started_before is not None else None
    except ValueError as e:
        return _err("VALIDATION_ERROR", f"started_before invalid: {e}")

    # Permissions: no auth model in schema; treat caller as permitted.
    # "FORBIDDEN" mentioned by tool description is not in allowed error codes; use UNAUTHORIZED when needed.
    # With ambient auth and no ACLs, never refuse a well-formed request.
    ops = _load("filesystem_operations.json")
    sessions = _load("sessions.json")

    # Observable service dynamics: record this list call as an auditable operation row.
    ts0 = datetime.datetime.now(datetime.timezone.utc)
    try:
        import secrets
        op_id = "op_" + secrets.token_hex(10)
    except Exception:
        op_id = "op_" + str(int(ts0.timestamp() * 1000000))

    # choose a session_id context for logging if provided, else any active session if exists, else leave None
    log_session_id = session_id
    if log_session_id is None:
        active = next((s for s in sessions if s.get("status") == "active"), None)
        log_session_id = active.get("id") if isinstance(active, dict) else (sessions[0].get("id") if sessions else "unknown_session")

    op_row = {
        "id": op_id,
        "session_id": log_session_id,
        "tool_name": "list_files",
        "status": "received",
        "parameters": {
            "session_id": session_id,
            "status": status,
            "tool_name": tool_name,
            "started_after": started_after,
            "started_before": started_before,
            "limit": limit,
            "cursor": cursor,
            "_endpoint": "list_filesystem_operations",
        },
        "resolved_base_path": None,
        "source_path_input": None,
        "source_path_resolved": None,
        "destination_path_input": None,
        "destination_path_resolved": None,
        "node_id": None,
        "destination_node_id": None,
        "result_summary": None,
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    ops.append(op_row)
    _save("filesystem_operations.json", ops)

    def _set_op_status(new_status, result_summary=None, error_code=None, error_message=None):
        nonlocal ops
        now_iso = _now_iso()
        allowed = {
            "received": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        for r in ops:
            if r.get("id") == op_id:
                cur = r.get("status")
                if new_status not in allowed.get(cur, []):
                    r["updated_at"] = now_iso
                    r["error_code"] = "INVALID_TRANSITION"
                    r["error_message"] = f"Illegal status transition {cur} -> {new_status}"
                    if cur in ("received", "running"):
                        r["status"] = "failed"
                        r["started_at"] = r.get("started_at") or now_iso
                        r["finished_at"] = now_iso
                    _save("filesystem_operations.json", ops)
                    return
                if new_status in ("running", "succeeded", "failed"):
                    r["started_at"] = r.get("started_at") or now_iso
                r["status"] = new_status
                r["updated_at"] = now_iso
                if new_status in ("succeeded", "failed"):
                    r["finished_at"] = now_iso
                r["result_summary"] = result_summary
                r["error_code"] = error_code
                r["error_message"] = error_message
                _save("filesystem_operations.json", ops)
                return

    _set_op_status("running")

    # Build filtered list excluding this logging op itself from returned operations to prevent self-noise
    def _dt_from_op(o):
        v = o.get("started_at") or o.get("created_at")
        if not isinstance(v, str):
            return None
        vv = v
        if vv.endswith("Z"):
            vv = vv[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(vv)
        except Exception:
            return None

    filtered = []
    for o in ops:
        if o.get("id") == op_id:
            continue
        if session_id is not None and o.get("session_id") != session_id:
            continue
        if status is not None and o.get("status") != status:
            continue
        if tool_name is not None and o.get("tool_name") != tool_name:
            continue
        odt = _dt_from_op(o)
        if dt_after is not None:
            if odt is None or not (odt > dt_after):
                continue
        if dt_before is not None:
            if odt is None or not (odt < dt_before):
                continue
        filtered.append(o)

    # Sort: most recent first by started_at then created_at
    def _sort_key(o):
        odt = _dt_from_op(o)
        if odt is None:
            odt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return odt

    filtered.sort(key=_sort_key, reverse=True)

    # Cursor: opaque index encoded as "i:<offset>"
    offset = 0
    if cursor is not None:
        c = cursor.strip()
        if not c.startswith("i:"):
            _set_op_status("failed", error_code="VALIDATION_ERROR", error_message="Invalid cursor format")
            return _err("VALIDATION_ERROR", "Invalid cursor format")
        try:
            offset = int(c.split(":", 1)[1])
        except ValueError:
            _set_op_status("failed", error_code="VALIDATION_ERROR", error_message="Invalid cursor value")
            return _err("VALIDATION_ERROR", "Invalid cursor value")
        if offset < 0:
            _set_op_status("failed", error_code="VALIDATION_ERROR", error_message="Invalid cursor value")
            return _err("VALIDATION_ERROR", "Invalid cursor value")

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"i:{next_offset}" if has_more else None

    _set_op_status("succeeded", result_summary={"returned": len(page), "total": total, "has_more": has_more})

    return {
        "operations": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
